<script setup lang="ts">import{onMounted,ref}from"vue";import{call}from"../api";import{useSettingsStore}from"../stores/settings";const s=useSettingsStore(),target=ref(""),trash=ref<any>(null),message=ref("");onMounted(async()=>{await s.init();trash.value=await call("trash_list")});async function save(){if(s.config)await s.update(s.config);message.value="设置已保存"}async function migrate(){if(target.value){await s.migrate(target.value);message.value="数据目录已迁移"}}async function action(kind:string,id:string,command:string){await call(command,{kind,id});trash.value=await call("trash_list")}</script><template><section v-if="s.config" class="settings"><h2>设置</h2><label>主题<select v-model="s.config.theme" class="input"><option value="system">跟随系统</option><option value="dark">深色</option><option value="light">浅色</option></select></label><label>热角<select v-model="s.config.hotCorner" class="input"><option value="off">关闭</option><option value="top-left">左上</option><option value="top-right">右上</option><option value="bottom-left">左下</option><option value="bottom-right">右下</option></select></label><label>全局快捷键<input v-model="s.config.hotkey" class="input"></label><label>GitHub 刷新间隔（分钟，0 为关闭）<input v-model.number="s.config.githubRefreshIntervalMinutes" type="number" class="input"></label><label><input v-model="s.config.autostart" type="checkbox" @change="s.setAutostart(s.config!.autostart)"> 开机自启</label><button class="btn primary" @click="save">应用设置</button><h3>数据目录</h3><p>{{s.config.dataDir}}</p><div class="toolbar"><input v-model="target" class="input" placeholder="输入新的绝对目录"><button class="btn" @click="migrate">迁移</button></div><h3>回收站</h3><template v-for="[kind,rows] in [['todoList',trash?.todoLists],['todoItem',trash?.todoItems],['note',trash?.notes]]" :key="kind"><div v-for="row in rows" :key="row.id" class="trash-row"><span>{{row.title}}</span><button class="btn" @click="action(kind,row.id,'trash_restore')">恢复</button><button class="btn danger" @click="action(kind,row.id,'trash_delete_permanently')">永久删除</button></div></template><p>{{message}}</p></section></template>
